			expect(labelRef).toBeDefined();
			const mountRoot = document.createElement("div");
			document.body.appendChild(mountRoot);
			let revealApi: Reveal.Api | undefined;
			let autoAnimateCount = 0;
			act(() => {
				mountPresentation(mountRoot, deck, {
					hash: false,
					slideNumber: false,
					surfaceChrome: false,
					onRevealReady: (api) => {
