  onDeleteSelection,
  rootStyle,
  asideStyle,
  showAside = true,
  showEngagement = false,
  onEngagementChange,
  onSearchChange,
  fillHost = false,
  captureGlobalKeys = true,
  asideHost = null,
  hideModelDefinitionControls = false,
  frameloop,
