    it("resolves a curve point by arc-length t along an entity's polyline", () => {
      const unregister = registerIntroductionSurfaceResolver("demo.curve", {
        entity: (domain, entityId) => {
          if (domain !== "attraction" || entityId !== "a1") return null;
          return {
            point: { x: 50, y: 0 },
            polyline: [
