          playing={false}
          rate={1}
          muted={false}
          captionsOn
          recording
          recordAvailable
          chapters={[{ id: "start", title: "Start", atMs: 0 }]}
          clock={clock}
          onPlayPause={() => {}}
          onStop={() => {}}
          onSeek={() => {}}
          onRateChange={() => {}}
          onMutedChange={() => {}}
          onCaptionsChange={() => {}}
          onRecordToggle={() => {}}
          onAddChapter={() => {}}
        />,
