/** @emoji 🪟️ Window descriptor rendered inside {@link Mode}. */
export interface ModeWindowDescriptor extends Omit<WindowConfig, "children" | "onOpenInNewWindow" | "onMaximize" | "onMinimize" | "onClose"> {
  title?: UiLabel;
  iconId: IconName;
  children: React.ReactNode;
