type GemojiEntry = {
  emoji?: string;
  aliases?: string[];
};

/** @emoji 🔖️ Builds universal shortcode tables (GitHub-style emoji aliases + UI catalog ids). */
async function generateShortcodes(icons: Record<string, string>, generatedDir: string): Promise<void> {
  mkdirSync(generatedDir, { recursive: true });
  const emoji: Record<string, string> = {};
  const catalog = Object.keys(icons).sort();

  try {
    const res = await fetch("https://raw.githubusercontent.com/github/gemoji/master/db/emoji.json");
    if (!res.ok) {
      throw new Error(`gemoji fetch failed: ${res.status}`);
    }
    const entries = (await res.json()) as GemojiEntry[];
    for (const entry of entries) {
      const glyph = entry.emoji?.trim();
      if (!glyph) continue;
      for (const alias of entry.aliases ?? []) {
        const key = alias.trim().toLowerCase();
        if (key !== "" && !(key in emoji)) {
          emoji[key] = glyph;
        }
      }
    }
  } catch (err) {
    console.warn("[asset] gemoji fetch failed; keeping existing emoji shortcodes if present", err);
    const existingPath = join(generatedDir, "🔣️shortcodes.json");
    if (existsSync(existingPath)) {
      const existing = JSON.parse(readFileSync(existingPath, "utf8")) as { emoji?: Record<string, string> };
      Object.assign(emoji, existing.emoji ?? {});
    }
  }

  for (const id of catalog) {
    if (!(id in emoji)) {
      continue;
    }
    delete emoji[id];
  }

  const payload = { emoji, catalog };
  writeFileSync(join(generatedDir, "🔣️shortcodes.json"), `${JSON.stringify(payload, null, 2)}\n`, "utf8");

  const emojiEntries = Object.keys(emoji)
    .sort()
    .map((key) => `  ${JSON.stringify(key)}: ${JSON.stringify(emoji[key])},`)
    .join("\n");
  const catalogEntries = catalog.map((id) => `  ${JSON.stringify(id)},`).join("\n");
  const tsBody = `// Generated by asset/script.ts — do not edit.
export const SHORTCODE_EMOJI = {
${emojiEntries}
} as const;

export type ShortcodeEmojiName = keyof typeof SHORTCODE_EMOJI;

export const SHORTCODE_CATALOG = [
${catalogEntries}
] as const;

export type ShortcodeCatalogName = (typeof SHORTCODE_CATALOG)[number];

/** @emoji 🔍️ Resolves a shortcode body (without colons) to emoji glyph when known. */
export function shortcodeEmoji(code: string): string | undefined {
  const key = code.trim().toLowerCase();
  return (SHORTCODE_EMOJI as Record<string, string>)[key];
}

/** @emoji 🔍️ True when the shortcode body names a vendored UI catalog icon. */
export function shortcodeCatalogKey(code: string): ShortcodeCatalogName | undefined {
  const key = code.trim();
  return (SHORTCODE_CATALOG as readonly string[]).includes(key) ? (key as ShortcodeCatalogName) : undefined;
}
`;
  writeFileSync(join(generatedDir, "🟦️shortcodes.ts"), tsBody, "utf8");
  console.log(`[asset] generated ${Object.keys(emoji).length} emoji + ${catalog.length} catalog shortcodes`);
}
//#endregion 🧬️Codegen

//#region 🚀️Commands
function catalogDirs(assetsDir: string): { iconsDir: string; generatedDir: string } {
  const iconsDir = join(assetsDir, "🔣️icons");
  const generatedDir = join(iconsDir, "🤖️generated");
  return { iconsDir, generatedDir };
}

function runGenerate(target: string): void {
  const assetsDir = assetsRoot();
  const { iconsDir, generatedDir } = catalogDirs(assetsDir);
  mkdirSync(generatedDir, { recursive: true });
  const icons = readCatalogSvgs(iconsDir);
  writeCatalogReadme(assetsDir, Object.keys(icons));
  if (target === "js" || target === "all") generateJs(icons, generatedDir);
  if (target === "net" || target === "all") generateCs(icons, generatedDir);
  if (target === "py" || target === "all") generatePy(icons, generatedDir);
  if (target === "rust" || target === "all") generateRust(icons, generatedDir);
  console.log(`[asset] generated ${Object.keys(icons).length} icons → ${target}`);
}

async function runGenerateAll(): Promise<void> {
  const assetsDir = assetsRoot();
  const { iconsDir, generatedDir } = catalogDirs(assetsDir);
  mkdirSync(generatedDir, { recursive: true });
  const icons = readCatalogSvgs(iconsDir);
  writeCatalogReadme(assetsDir, Object.keys(icons));
  generateJs(icons, generatedDir);
  generateCs(icons, generatedDir);
  generatePy(icons, generatedDir);
  generateRust(icons, generatedDir);
  await generateShortcodes(icons, generatedDir);
  console.log(`[asset] generated ${Object.keys(icons).length} icons + shortcodes → all`);
}
//#endregion 🚀️Commands

